import React from 'react';

interface SkillTooltipProps {
    text: string;
    isClosing: boolean;
}

export const SkillTooltip: React.FC<SkillTooltipProps> = ({ text, isClosing }) => {
    return (
        <div 
            className={`absolute bottom-full left-1/2 -translate-x-1/2 mb-1.5 w-32 z-[100] pointer-events-none origin-bottom ${isClosing ? 'animate-scale-out' : 'animate-scale-in'}`}
        >
            <div className="bg-white dark:bg-stone-100 text-stone-900 shadow-xl text-[10px] p-2 rounded-lg relative text-center leading-tight font-semibold border border-stone-200">
                {text}
                <div className="absolute top-full left-1/2 -translate-x-1/2 border-4 border-transparent border-t-white dark:border-t-stone-100"></div>
            </div>
        </div>
    );
};

import React, { useState, useRef } from 'react';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';
import { STATIC_BACKGROUNDS, DYNAMIC_BACKGROUNDS, NUMBER_COLORS, SKILLS, SOUND_PACKS } from '../../utils/constants';
import { SkillTooltip } from '../ui/SkillTooltip';

interface StoreScreenProps {
    points: number;
    onBack: () => void;
    purchasedSkills: string[];
    purchasedBackgrounds: string[];
    purchasedNumberColors: string[];
    purchasedSoundPacks: string[];
    selectedBackgroundId: string | null;
    selectedNumberColorId: string;
    selectedSoundPackId: string;
    onPurchase: (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => void;
    onSelectBackground: (id: string) => void;
    onSelectNumberColor: (id: string) => void;
    onSelectSoundPack: (id: string) => void;
}

export const StoreScreen: React.FC<StoreScreenProps> = ({
    points,
    onBack,
    purchasedSkills,
    purchasedBackgrounds,
    purchasedNumberColors,
    purchasedSoundPacks,
    selectedBackgroundId,
    selectedNumberColorId,
    selectedSoundPackId,
    onPurchase,
    onSelectBackground,
    onSelectNumberColor,
    onSelectSoundPack
}) => {
    const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);
    const [isClosing, setIsClosing] = useState(false);
    const closeTimeoutRef = useRef<NodeJS.Timeout | null>(null);

    const closeTooltip = () => {
        if (!activeTooltipId || isClosing) return;
        setIsClosing(true);
        if (closeTimeoutRef.current) clearTimeout(closeTimeoutRef.current);
        closeTimeoutRef.current = setTimeout(() => {
            setActiveTooltipId(null);
            setIsClosing(false);
        }, 150); // Matches scale-out duration
    };

    const handleItemClick = (e: React.MouseEvent, id: string, description: string, action?: () => void) => {
        e.stopPropagation();
        sounds.playClick();

        if (activeTooltipId === id) {
            if (action) action();
            closeTooltip();
        } else {
            if (activeTooltipId) {
                // Instantly switch if another is open
                setActiveTooltipId(id);
                setIsClosing(false);
            } else {
                setActiveTooltipId(id);
                setIsClosing(false);
            }
        }
    };

    return (
        <div 
            className="flex-1 w-full flex flex-col items-center overflow-hidden" 
            onClick={closeTooltip}
        >
             <div className="w-full max-w-md flex items-start px-6 pb-6 relative shrink-0 pt-[60px]">
                  <button onClick={onBack} className="absolute left-6 top-[20px] p-2 rounded-full hover:bg-stone-200 transition -ml-2 text-t-icon">
                      <Icons.Back className="w-6 h-6" />
                  </button>
                  <div className="w-full text-center mt-2 pointer-events-none"><h1 className="text-xl font-bold text-t-primary">Store</h1></div>
                  <div className="absolute right-6 top-[20px] flex items-center gap-1 bg-t-surface px-3 py-2 rounded-full shadow-sm border border-t-border">
                      <span className="text-sm font-bold text-t-primary">{points}</span>
                      <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                  </div>
             </div>

             <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">
                  <div className="w-full max-w-md space-y-8">

                      {/* SKILLS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Skills</h2>
                          <div className="grid grid-cols-5 gap-2">{SKILLS.map(skill => {
                              const isPurchased = purchasedSkills.includes(skill.id);
                              const showTooltip = activeTooltipId === skill.id;

                              return (
                                  <div key={skill.id} className="flex flex-col items-center gap-1 relative">
                                      {showTooltip && <SkillTooltip text={skill.description} isClosing={isClosing} />}

                                      <button 
                                          onClick={(e) => {
                                              if (!isPurchased) {
                                                  onPurchase(skill, 'skill');
                                              } else {
                                                  handleItemClick(e, skill.id, skill.description);
                                              }
                                          }} 
                                          className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all ${isPurchased ? 'bg-t-surface ring-2 ring-inset ring-blue-500' : 'bg-t-surface active:scale-95'}`}
                                      >
                                          <div className={`flex items-center justify-center w-full h-full ${!isPurchased ? 'pb-4' : ''}`}>
                                              <skill.icon className={`w-8 h-8 ${skill.class}`} />
                                          </div>
                                          {!isPurchased && (
                                              <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5">
                                                  <span className="text-sm font-bold text-t-primary leading-none">{skill.cost}</span>
                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                              </div>
                                          )}
                                      </button>
                                      <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{skill.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>

                      {/* BACKGROUNDS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Backgrounds</h2>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Static</h3>
                              <div className="grid grid-cols-5 gap-2">{STATIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1">
                                          <button onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 ${bg.class} ${!isSelected && bg.id === 'bg-default' ? 'ring-1 ring-inset ring-stone-900/10' : ''} ${!isPurchased ? 'opacity-90' : ''}`}>
                                              <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: bg.id === 'bg-default' ? 'calc(var(--overlay-opacity) * 0.6)' : 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              {isSelected && <div className="absolute inset-0 border-2 border-blue-500 rounded-xl z-20 pointer-events-none"></div>}
                                              {!isPurchased && (
                                                  <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                      <span className="text-sm font-bold text-t-primary leading-none">{bg.cost}</span>
                                                      <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                  </div>
                                              )}
                                          </button>
                                          <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Atmosphere</h3>
                              <div className="grid grid-cols-5 gap-2">{DYNAMIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1">
                                          <button onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 ${bg.class} ${!isPurchased ? 'opacity-90' : ''}`}>
                                              <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              {isSelected && <div className="absolute inset-0 border-2 border-blue-500 rounded-xl z-20 pointer-events-none"></div>}
                                              {!isPurchased && (
                                                  <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                      <span className="text-sm font-bold text-t-primary leading-none">{bg.cost}</span>
                                                      <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                  </div>
                                              )}
                                          </button>
                                          <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                      </div>

                      {/* SOUND PACKS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Sound Packs</h2>
                          <div className="grid grid-cols-5 gap-2">{SOUND_PACKS.map(pack => {
                              const isPurchased = purchasedSoundPacks.includes(pack.id);
                              const isSelected = selectedSoundPackId === pack.id;
                              const showTooltip = activeTooltipId === pack.id;

                              return (
                                  <div key={pack.id} className="flex flex-col items-center gap-1 relative">
                                      {showTooltip && <SkillTooltip text={pack.description} isClosing={isClosing} />}

                                      <button 
                                          onClick={(e) => {
                                              if (!isPurchased) {
                                                  onPurchase(pack, 'sound');
                                              } else {
                                                  handleItemClick(e, pack.id, pack.description, () => onSelectSoundPack(pack.id));
                                              }
                                          }} 
                                          className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all ${isSelected ? 'bg-t-surface ring-2 ring-inset ring-blue-500' : 'bg-t-surface active:scale-95'}`}
                                      >
                                          <div className={`flex items-center justify-center w-full h-full ${!isPurchased ? 'pb-4' : ''}`}>
                                              <pack.icon className={`w-8 h-8 text-t-primary`} />
                                          </div>
                                          {!isPurchased && (
                                              <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5">
                                                  <span className="text-sm font-bold text-t-primary leading-none">{pack.cost}</span>
                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                              </div>
                                          )}
                                      </button>
                                      <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{pack.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>

                      {/* NUMBER COLORS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Number Styles</h2>
                          <div className="grid grid-cols-5 gap-2">{NUMBER_COLORS.map(num => {
                              const isPurchased = purchasedNumberColors.includes(num.id);
                              const isSelected = selectedNumberColorId === num.id;
                              return (
                                  <div key={num.id} className="flex flex-col items-center gap-1">
                                      <button onClick={() => isPurchased ? onSelectNumberColor(num.id) : onPurchase(num, 'num')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 bg-t-surface ${isSelected ? 'ring-2 ring-inset ring-blue-500' : ''}`}>
                                          <div className={`flex items-center justify-center w-full h-full ${!isPurchased ? 'pb-4' : ''}`}>
                                              <span className={`text-3xl font-bold ${num.uiClass}`}>5</span>
                                          </div>
                                          {!isPurchased && (
                                              <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                  <span className="text-sm font-bold text-t-primary leading-none">{num.cost}</span>
                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                              </div>
                                          )}
                                      </button>
                                      <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{num.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>
                  </div>
                  <div className="h-safe-bottom w-full shrink-0" />
             </div>
        </div>
    );
};

import React from 'react';
import { Icons } from '../ui/Icons';
import { SkillTooltip } from '../ui/SkillTooltip';
import { SKILLS } from '../../utils/constants';

interface GameControlsProps {
    canUndo: boolean;
    canErase: boolean;
    isPencilMode: boolean;
    onUndo: (e: React.MouseEvent) => void;
    onErase: (e: React.MouseEvent) => void;
    onTogglePencil: (e: React.MouseEvent) => void;
    purchasedSkills: string[];
    // Skill specific props
    isAutoAvailable: boolean;
    scanUses: number;
    isScanning: boolean;
    scanCooldown: boolean;
    revealUses: number;
    revealingCell: {r: number, c: number} | null;
    onAutoFill: (e: React.MouseEvent) => void;
    onScan: (e: React.MouseEvent) => void;
    onReveal: (e: React.MouseEvent) => void;
    // Tooltip State
    activeTooltipId: string | null;
    isClosing: boolean;
    onSkillClick: (e: React.MouseEvent, skillId: string, trigger: () => void) => void;
}

export const GameControls: React.FC<GameControlsProps> = ({
    canUndo,
    canErase,
    isPencilMode,
    onUndo,
    onErase,
    onTogglePencil,
    purchasedSkills,
    isAutoAvailable,
    scanUses,
    isScanning,
    scanCooldown,
    revealUses,
    revealingCell,
    onAutoFill,
    onScan,
    onReveal,
    activeTooltipId,
    isClosing,
    onSkillClick
}) => {
    // Helper for common enabled/disabled styles
    const getBaseButtonStyle = (isEnabled: boolean) => 
        isEnabled 
            ? 'text-stone-900 dark:text-stone-100 cursor-pointer hover:brightness-95 active:scale-95' 
            : 'text-stone-300 dark:text-stone-600 cursor-not-allowed';

    const getBaseContainerStyle = (isEnabled: boolean) => 
        isEnabled
            ? 'bg-white dark:bg-stone-800 border-stone-300 dark:border-stone-600'
            : 'bg-t-surface-sec border-t-border dark:bg-stone-800/50 dark:border-stone-700';

    return (
        <div className="flex justify-between w-full">
            {/* Reveal Skill Button */}
            {purchasedSkills.includes('skill-reveal') && (
                    <button 
                        onClick={(e) => onSkillClick(e, 'skill-reveal', () => onReveal(e))} 
                        className={`flex flex-col items-center gap-1 transition relative ${getBaseButtonStyle(revealUses > 0 && !revealingCell)}`}
                        disabled={!!revealingCell}
                    >
                    {activeTooltipId === 'skill-reveal' && <SkillTooltip text={SKILLS.find(s => s.id === 'skill-reveal')?.description || ""} isClosing={isClosing} />}
                    <div className={`p-3 rounded-full border shadow-sm transition-all duration-300 relative ${getBaseContainerStyle(revealUses > 0)}`}>
                        <Icons.Reveal className={`w-5 h-5 ${revealUses > 0 ? 'text-purple-600 dark:text-purple-400' : 'text-stone-300 dark:text-stone-600'}`} />
                        <div className={`absolute -top-1.5 -right-1.5 w-5 h-5 rounded-full flex items-center justify-center text-xs font-bold border-2 border-t-surface leading-none ${revealUses > 0 ? 'bg-blue-600 text-white' : 'bg-stone-300 text-white dark:bg-stone-600'}`}>
                                {revealUses > 0 ? revealUses : '+'}
                        </div>
                    </div>
                    <span className="text-xs font-medium">Reveal</span>
                </button>
            )}

            {/* Scan Skill Button */}
            {purchasedSkills.includes('skill-scan') && (
                    <button 
                        onClick={(e) => onSkillClick(e, 'skill-scan', () => onScan(e))} 
                        className={`flex flex-col items-center gap-1 transition relative ${getBaseButtonStyle(scanUses > 0 && !scanCooldown && !isScanning)}`}
                        disabled={scanUses <= 0 || scanCooldown || isScanning}
                    >
                    {activeTooltipId === 'skill-scan' && <SkillTooltip text={SKILLS.find(s => s.id === 'skill-scan')?.description || ""} isClosing={isClosing} />}
                    <div className={`p-3 rounded-full border shadow-sm transition-all duration-300 relative ${getBaseContainerStyle(scanUses > 0 && !scanCooldown && !isScanning)}`}>
                        <Icons.Scan className={`w-5 h-5 ${scanUses > 0 && !scanCooldown && !isScanning ? 'text-red-600 dark:text-red-400' : 'text-stone-300 dark:text-stone-600'}`} />
                        {scanUses > 0 && (
                            <div className={`absolute -top-1.5 -right-1.5 w-5 h-5 rounded-full flex items-center justify-center text-xs font-bold border-2 border-t-surface leading-none ${scanUses > 0 ? 'bg-blue-600 text-white' : 'hidden'}`}>
                                {scanUses}
                            </div>
                        )}
                    </div>
                    <span className="text-xs font-medium">Scan</span>
                </button>
            )}

            {/* Auto Skill Button */}
            {purchasedSkills.includes('skill-auto') && (
                <button 
                    onClick={(e) => onSkillClick(e, 'skill-auto', () => onAutoFill(e))} 
                    className={`flex flex-col items-center gap-1 transition relative active:scale-95 ${isAutoAvailable ? 'cursor-pointer text-amber-700 dark:text-amber-400' : 'cursor-not-allowed text-stone-300 dark:text-stone-600'}`}
                    disabled={!isAutoAvailable}
                >
                    {activeTooltipId === 'skill-auto' && <SkillTooltip text={SKILLS.find(s => s.id === 'skill-auto')?.description || ""} isClosing={isClosing} />}
                    <div className={`p-3 rounded-full border shadow-sm transition-all duration-300 ${
                        isAutoAvailable 
                        ? 'bg-amber-100 border-amber-300 ring-1 ring-amber-200 dark:bg-amber-900/30 dark:border-amber-700 dark:ring-amber-900/50' 
                        : 'bg-t-surface-sec border-t-border dark:bg-stone-800/50 dark:border-stone-700'
                    }`}>
                        <Icons.Auto className={`w-5 h-5 ${isAutoAvailable ? 'text-amber-600 dark:text-amber-400 animate-pulse' : 'text-stone-300 dark:text-stone-600'}`} />
                    </div>
                    <span className="text-xs font-medium">Auto</span>
                </button>
            )}

            {/* UNDO BUTTON */}
            <button 
                onClick={onUndo} 
                disabled={!canUndo}
                className={`flex flex-col items-center gap-1 transition ${getBaseButtonStyle(canUndo)}`}
            >
                <div className={`p-3 rounded-full border shadow-sm transition-colors ${getBaseContainerStyle(canUndo)}`}>
                    <Icons.Undo className={`w-5 h-5 ${canUndo ? 'text-stone-700 dark:text-stone-300' : 'text-stone-300 dark:text-stone-600'}`} />
                </div>
                <span className="text-xs font-medium">Undo</span>
            </button>

            {/* PENCIL BUTTON */}
            <button 
                onClick={onTogglePencil} 
                className={`flex flex-col items-center gap-1 active:scale-95 transition cursor-pointer hover:brightness-95 ${isPencilMode ? 'text-blue-700 dark:text-blue-300' : 'text-stone-900 dark:text-stone-100'}`}
            >
                <div className={`p-3 rounded-full border shadow-sm transition-colors ${
                    isPencilMode 
                    ? 'bg-blue-100 border-blue-400 dark:bg-blue-900/40 dark:border-blue-700' 
                    : 'bg-white dark:bg-stone-800 border-stone-300 dark:border-stone-600'
                }`}>
                    <Icons.Pencil className={`w-5 h-5 ${isPencilMode ? 'text-blue-600 dark:text-blue-400' : 'text-stone-700 dark:text-stone-300'}`} />
                </div>
                <span className="text-xs font-medium">Pencil</span>
            </button>

            {/* ERASE BUTTON */}
            <button 
                onClick={onErase} 
                disabled={!canErase}
                className={`flex flex-col items-center gap-1 transition ${getBaseButtonStyle(canErase)}`}
            >
                <div className={`p-3 rounded-full border shadow-sm transition-colors ${getBaseContainerStyle(canErase)}`}>
                    <Icons.Erase className={`w-5 h-5 ${canErase ? 'text-stone-700 dark:text-stone-300' : 'text-stone-300 dark:text-stone-600'}`} />
                </div>
                <span className="text-xs font-medium">Erase</span>
            </button>
        </div>
    );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Difficulty, AppSettings, Board } from '../types';
import { useSudokuBoard } from '../hooks/useSudokuBoard';
import { useGameSkills } from '../hooks/useGameSkills';
import { useGameTimer } from '../hooks/useGameTimer';
import { SudokuGrid } from './game/SudokuGrid';
import { GameControls } from './game/GameControls';
import { NumberPad } from './game/NumberPad';
import { WinModal } from './game/WinModal';
import { generateReplayVideo, ReplayMove } from '../utils/replay';
import { Storage } from '../utils/storage';
import { sounds } from '../utils/sound';
import { Icons } from './ui/Icons';
import { formatTimeShort } from '../utils/constants';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onReturnToMenu: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  settings: AppSettings;
  onEarnPoints: (amount: number) => void;
  currentPoints: number;
  isSettingsOpen: boolean;
  backgroundClass: string;
  numberColor: string;
  purchasedSkills: string[];
}

export const SudokuGame: React.FC<SudokuGameProps> = ({
  difficulty,
  levelId,
  onBack,
  onReturnToMenu,
  onComplete,
  onSettingsOpen,
  settings,
  onEarnPoints,
  currentPoints,
  isSettingsOpen,
  backgroundClass,
  numberColor,
  purchasedSkills
}) => {
  const [isPaused, setIsPaused] = useState(false);
  const [showRestartConfirm, setShowRestartConfirm] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [isEnding, setIsEnding] = useState(false);
  const [earnedPoints, setEarnedPoints] = useState(0);

  const [isGeneratingReplay, setIsGeneratingReplay] = useState(false);
  const [replayUrl, setReplayUrl] = useState<string | null>(null);
  const [showReplay, setShowReplay] = useState(false);

  const [animatingSections, setAnimatingSections] = useState<Set<string>>(new Set());
  const [showStartHint, setShowStartHint] = useState(false);

  // Tooltip State
  const [activeSkillTooltipId, setActiveSkillTooltipId] = useState<string | null>(null);
  const [isTooltipClosing, setIsTooltipClosing] = useState(false);
  const closeTooltipTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  const closeSkillTooltip = () => {
      if (!activeSkillTooltipId || isTooltipClosing) return;
      setIsTooltipClosing(true);
      if (closeTooltipTimeoutRef.current) clearTimeout(closeTooltipTimeoutRef.current);
      closeTooltipTimeoutRef.current = setTimeout(() => {
          setActiveSkillTooltipId(null);
          setIsTooltipClosing(false);
      }, 150);
  };

  const handleSkillClick = (e: React.MouseEvent, skillId: string, trigger: () => void) => {
      e.stopPropagation();
      sounds.playClick();

      if (activeSkillTooltipId === skillId) {
          trigger();
          closeSkillTooltip();
      } else {
          setActiveSkillTooltipId(skillId);
          setIsTooltipClosing(false);
      }
  };

  const savedProgress = Storage.getLevelProgress(difficulty, levelId);
  const [initialTime, setInitialTime] = useState(0);

  // Timer hook
  const { timer, setTimer } = useGameTimer(
      settings,
      isPaused,
      isCompleted,
      isEnding,
      isSettingsOpen,
      initialTime
  );

  const saveProgress = (currentBoard: Board, scanUsesVal?: number, revealUsesVal?: number) => {
      if (isCompleted || isEnding) return;
      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'in-progress',
          timeElapsed: timer,
          boardState: currentBoard,
          lastPlayed: Date.now(),
          scanUses: scanUsesVal !== undefined ? scanUsesVal : scanUses,
          revealUses: revealUsesVal !== undefined ? revealUsesVal : revealUses
      });
  };

  const handleSectionComplete = useCallback((sections: string[]) => {
      if (sections.length > 0) {
          sounds.playSectionComplete();
          setAnimatingSections(prev => {
              const next = new Set(prev);
              sections.forEach(s => next.add(s));
              return next;
          });
          setTimeout(() => {
              setAnimatingSections(prev => {
                  const next = new Set(prev);
                  sections.forEach(s => next.delete(s));
                  return next;
              });
          }, 1000);
      }
  }, []);

  const {
      board,
      setBoard,
      solvedBoard,
      initialBoardRef,
      history,
      setHistory,
      moveLog,
      isPencilMode,
      setIsPencilMode,
      selectedCell,
      setSelectedCell,
      activeNumber,
      setActiveNumber,
      conflicts,
      numberCounts,
      initializeBoard,
      handleCellClick,
      handleNumberInput,
      handleUndo,
      handleErase,
      checkCompletion,
      removeNotesFromPeers
