                                              {isPurchased && (
                                                  <button 
                                                      onClick={(e) => handleToggleClick(e, skill.id)}
                                                      className="p-1 active:scale-95 transition-transform"
                                                      aria-label={`Toggle ${skill.name}`}
                                                  >
                                                      <div className={`w-10 h-5 rounded-full relative transition-colors duration-300 border-2 ${isEnabled ? 'bg-blue-500 border-blue-600' : 'bg-stone-300 dark:bg-stone-700 border-stone-400 dark:border-stone-600'}`}>
                                                          <div className={`absolute top-0.5 w-3 h-3 rounded-full bg-white shadow-md transition-transform duration-300 ease-out ${isEnabled ? 'translate-x-5' : 'translate-x-0.5'}`}></div>
                                                      </div>
                                                  </button>
                                              )}
                                          </div>

                                          <div className="relative w-full">
                                              {showTooltip && <SkillTooltip text={skill.description} isClosing={isClosing} />}
                                              <button 
                                                  onClick={(e) => handleSkillClick(e, skill)} 
                                                  className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all ${isPurchased ? (isEnabled ? 'bg-t-surface ring-2 ring-inset ring-blue-500' : 'bg-t-surface-sec opacity-60 grayscale') : 'bg-t-surface active:scale-95'}`}
                                              >
                                                  <div className={`flex items-center justify-center w-full h-full ${!isPurchased ? 'pb-4' : ''}`}>
                                                      <skill.icon className={`w-8 h-8 ${skill.class}`} />
                                                  </div>
