                                    <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                                </div>
                           </div>
                           <div className="flex flex-col">
                               <h1 className="text-3xl font-black text-t-primary leading-tight">Store</h1>
                               <p className="text-t-secondary text-sm font-medium">Personalize your journey</p>
                           </div>
                      </div>

                      {/* SKILLS SECTION */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-1 ml-1">Skills</h2>
                          <div className="grid grid-cols-5 gap-x-2 gap-y-1">
                              {SKILLS.map(skill => {
                                  const isPurchased = purchasedSkills.includes(skill.id);
                                  const isEnabled = enabledSkills.includes(skill.id);
                                  const showTooltip = activeTooltipId === skill.id;

                                  return (
                                      <div key={skill.id} className="flex flex-col items-center relative">

                                          {/* Toggle Area: Reduced height and margins to bring it closer to the container and title */}
                                          <div className="h-7 w-full flex items-end justify-center mb-0.5">
                                              {isPurchased && (
                                                  <button 
                                                      onClick={(e) => handleToggleClick(e, skill.id)}
                                                      className="p-0.5 active:scale-95 transition-transform"
                                                      aria-label={`Toggle ${skill.name}`}
                                                  >
                                                      <div className={`w-10 h-5 rounded-full relative transition-colors duration-300 border-2 ${isEnabled ? 'bg-blue-500 border-blue-600' : 'bg-stone-300 dark:bg-stone-700 border-stone-400 dark:border-stone-600'}`}>
                                                          <div className={`absolute top-0.5 w-3 h-3 rounded-full bg-white shadow-md transition-transform duration-300 ease-out ${isEnabled ? 'translate-x-5' : 'translate-x-0.5'}`}></div>
                                                      </div>
                                                  </button>
                                              )}
                                          </div>

