                              const isSelected = selectedSoundPackId === pack.id;
                              const showTooltip = activeTooltipId === pack.id;

                              return (
                                  <div key={pack.id} className="flex flex-col items-center gap-1 relative">
                                      {showTooltip && <SkillTooltip text={pack.description} isClosing={isClosing} />}

                                      <button 
