  const INTRO_FRAMES = Math.floor((INTRO_MS / 1000) * FPS);
  const FILL_FRAMES = Math.floor((FILL_MS / 1000) * FPS);
  const OUTRO_FRAMES = Math.floor((OUTRO_MS / 1000) * FPS);
  const TOTAL_FRAMES = INTRO_FRAMES + FILL_FRAMES + OUTRO_FRAMES;

  const c = {
    bg: isDark ? '#1c1917' : '#fafaf9',
    boardBg: isDark ? '#292524' : '#ffffff',
    gridLineThin: isDark ? '#57534e' : '#e7e5e4',
    gridLineThick: isDark ? '#a8a29e' : '#78716c',
    textFixed: isDark ? '#f5f5f4' : '#292524',
    textInput: '#3b82f6',
    successBorder: '#10b981',
    watermark: isDark ? '#57534e' : '#a8a29e',
  };

  const padding = 120;
  const boardSize = size - (padding * 2);
  const cellSize = boardSize / 9;
  const startX = padding;
  const startY = padding;

  const moveCount = moves.length;
  const moveFrames = new Int32Array(moveCount);
  const BUFFER_FRAMES = 6; 
  const availableFrames = Math.max(1, FILL_FRAMES - BUFFER_FRAMES);
  const frameStep = availableFrames / Math.max(1, moveCount);

  for (let i = 0; i < moveCount; i++) {
      moveFrames[i] = INTRO_FRAMES + Math.floor(i * frameStep);
  }

  // Draw Function (now purely visual)
  const drawBoard = (frame: number) => {
      ctx.fillStyle = c.bg;
      ctx.fillRect(0, 0, size, size);

      let globalOpacity = 1;
      let scale = 1;
      if (frame < INTRO_FRAMES) {
          const t = frame / INTRO_FRAMES;
          globalOpacity = t;
          scale = 0.95 + (0.05 * t);
      }

      ctx.save();
      ctx.translate(size/2, size/2);
      ctx.scale(scale, scale);
      ctx.translate(-size/2, -size/2);
      ctx.globalAlpha = globalOpacity;

      // Header
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = c.textFixed;
      ctx.font = 'bold 40px "Outfit", sans-serif';
      ctx.fillText(`${difficulty.toUpperCase()} • LEVEL ${levelId}`, size/2, padding / 2);

      // Watermark
      ctx.fillStyle = c.watermark;
      ctx.font = '500 30px "Outfit", sans-serif';
      ctx.fillText("OKU: SUDOKU", size/2, size - (padding / 2));

      // Board BG
      ctx.shadowColor = "rgba(0,0,0,0.1)";
      ctx.shadowBlur = 30;
      ctx.shadowOffsetY = 10;
      ctx.fillStyle = c.boardBg;
      const r = 32;
      ctx.beginPath();
      ctx.roundRect(startX, startY, boardSize, boardSize, r);
      ctx.fill();
      ctx.shadowBlur = 0;
      ctx.shadowOffsetY = 0;

      // Clip
      ctx.save();
      ctx.beginPath();
      ctx.roundRect(startX, startY, boardSize, boardSize, r);
      ctx.clip();

      // Lines
      ctx.lineCap = 'butt';
      for (let i = 1; i < 9; i++) {
          const pos = i * cellSize;
          const isThick = i % 3 === 0;
          ctx.lineWidth = isThick ? 6 : 2;
          ctx.strokeStyle = isThick ? c.gridLineThick : c.gridLineThin;

          ctx.beginPath();
          ctx.moveTo(startX + pos, startY);
          ctx.lineTo(startX + pos, startY + boardSize);
          ctx.stroke();

          ctx.beginPath();
          ctx.moveTo(startX, startY + pos);
          ctx.lineTo(startX + boardSize, startY + pos);
          ctx.stroke();
      }
      ctx.restore();

      // Fixed Nums
      ctx.font = `600 ${cellSize * 0.6}px "Outfit", sans-serif`;
      ctx.fillStyle = c.textFixed;

      initialBoard.forEach(row => {
          row.forEach(cell => {
              if (cell.isFixed && cell.value) {
                  const cx = startX + (cell.col * cellSize) + (cellSize / 2);
                  const cy = startY + (cell.row * cellSize) + (cellSize / 2);
                  ctx.fillText(cell.value.toString(), cx, cy + (cellSize * 0.05));
              }
          });
      });

      // Moves
      if (frame >= INTRO_FRAMES) {
          ctx.font = `500 ${cellSize * 0.6}px "Outfit", sans-serif`;
          ctx.fillStyle = c.textInput;

          for (let i = 0; i < moveCount; i++) {
              const startFrame = moveFrames[i];

              if (frame >= startFrame) {
                  const move = moves[i];
                  const cx = startX + (move.col * cellSize) + (cellSize / 2);
                  const cy = startY + (move.row * cellSize) + (cellSize / 2);

                  const age = frame - startFrame;
                  let numScale = 1;
                  if (age < 6) {
                      numScale = 1.0 + (0.5 * (1 - (age / 6)));
                  }

                  ctx.save();
                  ctx.translate(cx, cy);
                  ctx.scale(numScale, numScale);
                  ctx.fillText(move.value.toString(), 0, (cellSize * 0.05));
                  ctx.restore();
              }
          }
      }

      // Success Outro
      if (frame >= INTRO_FRAMES + FILL_FRAMES) {
          const outroAge = frame - (INTRO_FRAMES + FILL_FRAMES);
          const BORDER_FRAME = 0;

          if (outroAge >= BORDER_FRAME) {
              const visualAge = outroAge - BORDER_FRAME;
              const alpha = Math.min(1, (visualAge + 1) / 5);

              ctx.lineWidth = 12;
              ctx.strokeStyle = c.successBorder;
              ctx.globalAlpha = alpha * globalOpacity;

              ctx.beginPath();
              ctx.roundRect(startX, startY, boardSize, boardSize, r);
              ctx.stroke();
          }
      }

      ctx.restore();
  };

  // Pre-render first frame
  drawBoard(0);

  // Create Stream & Recorder
  const stream = canvas.captureStream(FPS);
  const audioTrack = dest.stream.getAudioTracks()[0];
  if (audioTrack) {
      stream.addTrack(audioTrack);
  }

  let mimeType = 'video/webm';
  const possibleTypes = [
    'video/mp4; codecs=avc1',
    'video/mp4',
    'video/webm; codecs=vp9',
    'video/webm'
  ];

  for (const t of possibleTypes) {
      if (MediaRecorder.isTypeSupported(t)) {
          mimeType = t;
          break;
      }
  }

  let mediaRecorder: MediaRecorder;
  try {
      mediaRecorder = new MediaRecorder(stream, { mimeType, videoBitsPerSecond: 5000000 });
  } catch (e) {
      console.error("MediaRecorder creation failed", e);
      audioCtx.close();
      return null;
  }

  const chunks: Blob[] = [];
  mediaRecorder.ondataavailable = (e) => {
    if (e.data.size > 0) chunks.push(e.data);
  };

  const recordingPromise = new Promise<string | null>((resolve) => {
    mediaRecorder.onstop = () => {
      audioCtx.close();
      if (chunks.length === 0) {
           resolve(null);
           return;
      }
      const blob = new Blob(chunks, { type: mimeType });
      const url = URL.createObjectURL(blob);
      resolve(url);
    };
    mediaRecorder.onerror = (e) => {
        console.error("MediaRecorder error", e);
        audioCtx.close();
        resolve(null);
    };
  });

  // Start Recording
  try {
      mediaRecorder.start();
  } catch (e) {
      console.error("MediaRecorder start failed", e);
      audioCtx.close();
      return null;
  }

  // PRE-SCHEDULE AUDIO
  // We use the audioCtx timeline to schedule all events at the exact predicted frame times
  const baseTime = audioCtx.currentTime;

  // Schedule move pops
  for (let i = 0; i < moveCount; i++) {
    const scheduledTime = baseTime + (moveFrames[i] / FPS);
    playPop(i / Math.max(1, moveCount), scheduledTime);
  }

  // Schedule victory swell (happens exactly when outro starts)
  const victoryScheduledTime = baseTime + ((INTRO_FRAMES + FILL_FRAMES) / FPS);
  playVictory(victoryScheduledTime);

  // EXECUTION LOOP
  let currentFrame = 1;
  const intervalMs = 1000 / FPS;

  return new Promise((resolve) => {
      const interval = setInterval(() => {
          try {
              drawBoard(currentFrame);
              currentFrame++;

              if (currentFrame >= TOTAL_FRAMES) {
                  clearInterval(interval);
                  // Ensure audio has finished captured before stopping
                  setTimeout(() => {
                    mediaRecorder.stop();
                    recordingPromise.then(resolve);
                  }, 100);
              }
          } catch (e) {
              console.error("Error during recording loop", e);
              clearInterval(interval);
              try { mediaRecorder.stop(); } catch(e2) {}
              resolve(null);
          }
      }, intervalMs);
  });
}

import React, { useState, useRef } from 'react';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';
import { STATIC_BACKGROUNDS, DYNAMIC_BACKGROUNDS, NUMBER_COLORS, SKILLS, SOUND_PACKS } from '../../utils/constants';
import { SkillTooltip } from '../ui/SkillTooltip';

interface StoreScreenProps {
    points: number;
    onBack: () => void;
    purchasedSkills: string[];
    enabledSkills: string[];
    purchasedBackgrounds: string[];
    purchasedNumberColors: string[];
    purchasedSoundPacks: string[];
    selectedBackgroundId: string | null;
    selectedNumberColorId: string;
    selectedSoundPackId: string;
    onPurchase: (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => void;
    onSelectBackground: (id: string) => void;
    onSelectNumberColor: (id: string) => void;
    onSelectSoundPack: (id: string) => void;
    onToggleSkill: (id: string) => void;
}

export const StoreScreen: React.FC<StoreScreenProps> = ({
    points,
    onBack,
    purchasedSkills,
    enabledSkills,
    purchasedBackgrounds,
    purchasedNumberColors,
    purchasedSoundPacks,
    selectedBackgroundId,
    selectedNumberColorId,
    selectedSoundPackId,
    onPurchase,
    onSelectBackground,
    onSelectNumberColor,
    onSelectSoundPack,
    onToggleSkill
}) => {
    const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);
    const [isClosing, setIsClosing] = useState(false);
    const closeTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    const closeTooltip = () => {
        if (!activeTooltipId || isClosing) return;
        setIsClosing(true);
        if (closeTimeoutRef.current) clearTimeout(closeTimeoutRef.current);
        closeTimeoutRef.current = setTimeout(() => {
            setActiveTooltipId(null);
            setIsClosing(false);
        }, 150);
    };

    const handleItemTooltip = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        sounds.playClick();

        if (activeTooltipId === id) {
            closeTooltip();
        } else {
            setActiveTooltipId(id);
            setIsClosing(false);
        }
    };

    const handleSoundPackClick = (e: React.MouseEvent, pack: typeof SOUND_PACKS[0]) => {
        e.stopPropagation();
        const isPurchased = purchasedSoundPacks.includes(pack.id);
        const isSelected = selectedSoundPackId === pack.id;

        if (!isPurchased) {
            onPurchase(pack, 'sound');
        } else {
            if (!isSelected) {
                sounds.playClick();
                onSelectSoundPack(pack.id);
                if (activeTooltipId === pack.id) closeTooltip();
            } else {
                handleItemTooltip(e, pack.id);
            }
        }
    };

    const handleSkillClick = (e: React.MouseEvent, skill: typeof SKILLS[0]) => {
        e.stopPropagation();
        const isPurchased = purchasedSkills.includes(skill.id);

        if (!isPurchased) {
            onPurchase(skill, 'skill');
        } else {
            // If already purchased, clicking the card body shows the tooltip
            handleItemTooltip(e, skill.id);
        }
    };

    const handleToggleClick = (e: React.MouseEvent, skillId: string) => {
        e.stopPropagation(); // Stop bubbling to prevent tooltip from opening
        sounds.playClick();
        onToggleSkill(skillId);
    };

    return (
        <div 
            className="flex-1 w-full flex flex-col items-center overflow-hidden" 
            onClick={closeTooltip}
        >
             <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center pt-[60px]">
                  <div className="w-full max-w-md space-y-8">

                      {/* Integrated Navigation and Title Section */}
                      <div className="flex flex-col gap-4 mb-2">
                           <div className="flex justify-between items-center">
                                <button 
                                    onClick={(e) => { e.stopPropagation(); onBack(); }} 
                                    className="p-2 -ml-2 rounded-full hover:bg-stone-200 transition text-t-icon"
                                >
                                    <Icons.Back className="w-6 h-6" />
                                </button>
                                <div className="flex items-center gap-1 bg-t-surface px-3 py-2 rounded-full shadow-sm border border-t-border">
                                    <span className="text-sm font-bold text-t-primary">{points}</span>
                                    <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                                </div>
                           </div>
                           <div className="flex flex-col">
                               <h1 className="text-3xl font-black text-t-primary leading-tight">Store</h1>
                               <p className="text-t-secondary text-sm font-medium">Personalize your journey</p>
                           </div>
                      </div>

                      {/* SKILLS SECTION */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-3 ml-1">Skills</h2>
                          <div className="grid grid-cols-5 gap-x-2 gap-y-1">
                              {SKILLS.map(skill => {
                                  const isPurchased = purchasedSkills.includes(skill.id);
                                  const isEnabled = enabledSkills.includes(skill.id);
                                  const showTooltip = activeTooltipId === skill.id;

                                  return (
                                      <div key={skill.id} className="flex flex-col items-center relative">
                                          <div className="relative w-full">
                                              {showTooltip && <SkillTooltip text={skill.description} isClosing={isClosing} />}
                                              <button 
                                                  onClick={(e) => handleSkillClick(e, skill)} 
                                                  className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all border border-t-border ${isPurchased ? (isEnabled ? 'bg-t-surface' : 'bg-t-surface-sec opacity-60 grayscale') : 'bg-t-surface active:scale-95'}`}
                                              >
                                                  {/* Icon Area: Vertically shifted up to accommodate the bottom bar */}
                                                  <div className="flex items-center justify-center w-full h-full pb-7">
                                                      <skill.icon className={`w-7 h-7 ${skill.class}`} />
                                                  </div>

                                                  {/* Bottom Bar: Price or Toggle Switch */}
                                                  <div className="absolute bottom-0 inset-x-0 h-7 bg-t-surface-sec border-t border-t-border flex items-center justify-center">
                                                      {!isPurchased ? (
                                                          <div className="flex items-center gap-0.5 pointer-events-none">
                                                              <span className="text-[10px] font-bold text-t-primary leading-none">{skill.cost}</span>
                                                              <Icons.Diamond className="w-2.5 h-2.5 text-blue-500 fill-current" />
                                                          </div>
                                                      ) : (
                                                          <div 
                                                              onClick={(e) => handleToggleClick(e, skill.id)}
                                                              className="w-full h-full flex items-center justify-center cursor-pointer active:scale-90 transition-transform"
                                                              aria-label={`Toggle ${skill.name}`}
                                                          >
                                                               <div className={`w-7 h-3.5 rounded-full relative transition-colors duration-300 border ${isEnabled ? 'bg-blue-500 border-blue-600' : 'bg-stone-300 dark:bg-stone-700 border-stone-400 dark:border-stone-600'}`}>
                                                                  <div className={`absolute top-[1px] w-2 h-2 rounded-full bg-white shadow-sm transition-transform duration-300 ease-out ${isEnabled ? 'translate-x-3.5' : 'translate-x-[1px]'}`}></div>
                                                              </div>
                                                          </div>
                                                      )}
                                                  </div>
                                              </button>
                                          </div>
                                          <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full mt-1">{skill.name}</span>
                                      </div>
                                  );
                              })}
                          </div>
                      </div>

                      {/* BACKGROUNDS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Backgrounds</h2>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Static</h3>
                              <div className="grid grid-cols-5 gap-2">{STATIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1">
                                          <button onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 ${bg.class} ${!isSelected && bg.id === 'bg-default' ? 'ring-1 ring-inset ring-stone-900/10' : ''} ${!isPurchased ? 'opacity-90' : ''}`}>
                                              <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: bg.id === 'bg-default' ? 'calc(var(--overlay-opacity) * 0.6)' : 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              {isSelected && <div className="absolute inset-0 border-2 border-blue-500 rounded-xl z-20 pointer-events-none"></div>}
                                              {!isPurchased && (
                                                  <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                      <span className="text-sm font-bold text-t-primary leading-none">{bg.cost}</span>
                                                      <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                  </div>
                                              )}
                                          </button>
                                          <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Atmosphere</h3>
                              <div className="grid grid-cols-5 gap-2">{DYNAMIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1">
                                          <button onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 ${bg.class} ${!isPurchased ? 'opacity-90' : ''}`}>
                                              <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              {isSelected && <div className="absolute inset-0 border-2 border-blue-500 rounded-xl z-20 pointer-events-none"></div>}
                                              {!isPurchased && (
                                                  <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                      <span className="text-sm font-bold text-t-primary leading-none">{bg.cost}</span>
                                                      <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                  </div>
                                              )}
                                          </button>
                                          <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                      </div>

                      {/* SOUND PACKS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Sound Packs</h2>
                          <div className="grid grid-cols-5 gap-2">{SOUND_PACKS.map(pack => {
                              const isPurchased = purchasedSoundPacks.includes(pack.id);
                              const isSelected = selectedSoundPackId === pack.id;
                              const showTooltip = activeTooltipId === pack.id;

                              return (
                                  <div key={pack.id} className="flex flex-col items-center gap-1 relative">
                                      {showTooltip && <SkillTooltip text={pack.description} isClosing={isClosing} />}

                                      <button 
                                          onClick={(e) => handleSoundPackClick(e, pack)} 
                                          className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all ${isSelected ? 'bg-t-surface ring-2 ring-inset ring-blue-500' : 'bg-t-surface active:scale-95'}`}
                                      >
                                          <div className={`flex items-center justify-center w-full h-full ${!isPurchased ? 'pb-4' : ''}`}>
                                              <pack.icon className={`w-8 h-8 text-t-primary`} />
                                          </div>
                                          {!isPurchased && (
                                              <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5">
                                                  <span className="text-sm font-bold text-t-primary leading-none">{pack.cost}</span>
                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                              </div>
                                          )}
                                      </button>
                                      <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{pack.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>

                      {/* NUMBER COLORS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Number Styles</h2>
                          <div className="grid grid-cols-5 gap-2">{NUMBER_COLORS.map(num => {
                              const isPurchased = purchasedNumberColors.includes(num.id);
                              const isSelected = selectedNumberColorId === num.id;
                              return (
                                  <div key={num.id} className="flex flex-col items-center gap-1">
                                      <button onClick={() => isPurchased ? onSelectNumberColor(num.id) : onPurchase(num, 'num')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 bg-t-surface ${isSelected ? 'ring-2 ring-inset ring-blue-500' : ''}`}>
                                          <div className={`flex items-center justify-center w-full h-full ${!isPurchased ? 'pb-4' : ''}`}>
                                              <span className={`text-3xl font-bold ${num.uiClass}`}>5</span>
                                          </div>
                                          {!isPurchased && (
                                              <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                  <span className="text-sm font-bold text-t-primary leading-none">{num.cost}</span>
                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                              </div>
                                          )}
                                      </button>
                                      <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{num.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>
                  </div>
                  <div className="h-safe-bottom w-full shrink-0" />
             </div>
        </div>
    );
};

import React, { useState, useRef } from 'react';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';
import { STATIC_BACKGROUNDS, DYNAMIC_BACKGROUNDS, NUMBER_COLORS, SKILLS, SOUND_PACKS } from '../../utils/constants';
import { SkillTooltip } from '../ui/SkillTooltip';

interface StoreScreenProps {
    points: number;
    onBack: () => void;
    purchasedSkills: string[];
    enabledSkills: string[];
    purchasedBackgrounds: string[];
    purchasedNumberColors: string[];
    purchasedSoundPacks: string[];
    selectedBackgroundId: string | null;
    selectedNumberColorId: string;
    selectedSoundPackId: string;
    onPurchase: (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => void;
    onSelectBackground: (id: string) => void;
    onSelectNumberColor: (id: string) => void;
    onSelectSoundPack: (id: string) => void;
    onToggleSkill: (id: string) => void;
}

export const StoreScreen: React.FC<StoreScreenProps> = ({
    points,
    onBack,
    purchasedSkills,
    enabledSkills,
    purchasedBackgrounds,
    purchasedNumberColors,
    purchasedSoundPacks,
    selectedBackgroundId,
    selectedNumberColorId,
    selectedSoundPackId,
    onPurchase,
    onSelectBackground,
    onSelectNumberColor,
    onSelectSoundPack,
    onToggleSkill
}) => {
    const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);
    const [isClosing, setIsClosing] = useState(false);
    const closeTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    const closeTooltip = () => {
