                                          <div className={`flex items-center justify-center w-full h-full ${!isPurchased ? 'pb-4' : ''}`}>
                                              <pack.icon className={`w-8 h-8 text-t-primary`} />
                                          </div>
                                          {!isPurchased && (
                                              <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5">
                                                  <span className="text-sm font-bold text-t-primary leading-none">{pack.cost}</span>
                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                              </div>
                                          )}
                                      </button>
                                      <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{pack.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>

                      {/* NUMBER COLORS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Number Styles</h2>
                          <div className="grid grid-cols-5 gap-2">{NUMBER_COLORS.map(num => {
                              const isPurchased = purchasedNumberColors.includes(num.id);
                              const isSelected = selectedNumberColorId === num.id;
                              return (
                                  <div key={num.id} className="flex flex-col items-center gap-1">
                                      <button onClick={() => isPurchased ? onSelectNumberColor(num.id) : onPurchase(num, 'num')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 bg-t-surface ${isSelected ? 'ring-2 ring-inset ring-blue-500' : ''}`}>
                                          <div className={`flex items-center justify-center w-full h-full ${!isPurchased ? 'pb-4' : ''}`}>
                                              <span className={`text-3xl font-bold ${num.uiClass}`}>5</span>
                                          </div>
                                          {!isPurchased && (
                                              <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                  <span className="text-sm font-bold text-t-primary leading-none">{num.cost}</span>
                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                              </div>
                                          )}
                                      </button>
                                      <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{num.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>
                  </div>
                  <div className="h-safe-bottom w-full shrink-0" />
             </div>
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
