import { useGameTimer } from '../hooks/useGameTimer';
import { SudokuGrid } from './game/SudokuGrid';
import { GameControls } from './game/GameControls';
import { NumberPad } from './game/NumberPad';
import { WinModal } from './game/WinModal';
import { generateReplayVideo, ReplayMove } from '../utils/replay';
import { Storage } from '../utils/storage';
import { sounds } from '../utils/sound';
import { Icons } from './ui/Icons';
import { formatTimeShort } from '../utils/constants';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onReturnToMenu: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  settings: AppSettings;
  onEarnPoints: (amount: number) => void;
  currentPoints: number;
  isSettingsOpen: boolean;
  backgroundClass: string;
  numberColor: string;
  purchasedSkills: string[];
}

export const SudokuGame: React.FC<SudokuGameProps> = ({
  difficulty,
  levelId,
  onBack,
  onReturnToMenu,
  onComplete,
  onSettingsOpen,
  settings,
  onEarnPoints,
  currentPoints,
  isSettingsOpen,
  backgroundClass,
  numberColor,
  purchasedSkills
}) => {
  const [isPaused, setIsPaused] = useState(false);
  const [showRestartConfirm, setShowRestartConfirm] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [isEnding, setIsEnding] = useState(false);
  const [earnedPoints, setEarnedPoints] = useState(0);

  const [isGeneratingReplay, setIsGeneratingReplay] = useState(false);
  const [replayUrl, setReplayUrl] = useState<string | null>(null);
  const [showReplay, setShowReplay] = useState(false);

  const [animatingSections, setAnimatingSections] = useState<Set<string>>(new Set());
  const [showStartHint, setShowStartHint] = useState(false);

  const savedProgress = Storage.getLevelProgress(difficulty, levelId);
  const [initialTime, setInitialTime] = useState(0);

  // Timer hook
  const { timer, setTimer } = useGameTimer(
      settings,
      isPaused,
      isCompleted,
      isEnding,
      isSettingsOpen,
      initialTime
  );

  const saveProgress = (currentBoard: Board, scanUsesVal?: number, revealUsesVal?: number) => {
      if (isCompleted || isEnding) return;
      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'in-progress',
          timeElapsed: timer,
          boardState: currentBoard,
          lastPlayed: Date.now(),
          scanUses: scanUsesVal !== undefined ? scanUsesVal : scanUses,
          revealUses: revealUsesVal !== undefined ? revealUsesVal : revealUses
      });
  };

  const handleSectionComplete = useCallback((sections: string[]) => {
      if (sections.length > 0) {
          sounds.playSectionComplete();
          setAnimatingSections(prev => {
              const next = new Set(prev);
              sections.forEach(s => next.add(s));
              return next;
          });
          setTimeout(() => {
              setAnimatingSections(prev => {
                  const next = new Set(prev);
                  sections.forEach(s => next.delete(s));
                  return next;
              });
          }, 1000);
      }
  }, []);

  const handleGameComplete = (completedBoard: Board) => {
      if (isCompleted || isEnding) return;
      setIsEnding(true);
      sounds.playWin();

      // Trigger full board completion animation
      setAnimatingSections(new Set(['full-board']));
      setTimeout(() => {
          setAnimatingSections(new Set());
      }, 1500);

      let points = 0;
      switch(difficulty) {
          case Difficulty.SuperEasy: points = 5; break;
          case Difficulty.Easy: points = 10; break;
          case Difficulty.Normal: points = 15; break;
          case Difficulty.Hard: points = 20; break;
          case Difficulty.Intense: points = 30; break;
          case Difficulty.Impossible: points = 50; break;
      }

      onEarnPoints(points);
      setEarnedPoints(points);

      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'completed',
          timeElapsed: timer,
          boardState: completedBoard,
          lastPlayed: Date.now(),
          scanUses,
          revealUses
      });

      if (settings.generateReplay) {
          generateReplay();
      }

      setTimeout(() => {
          setIsCompleted(true);
          onComplete();
      }, 1500);
  };

  const {
      board,
      setBoard,
      solvedBoard,
      initialBoardRef,
      history,
      setHistory,
      moveLog,
      isPencilMode,
      setIsPencilMode,
      selectedCell,
      setSelectedCell,
      activeNumber,
      setActiveNumber,
      conflicts,
      numberCounts,
      initializeBoard,
      handleCellClick,
      handleNumberInput,
      handleUndo,
      handleErase,
      checkCompletion,
      removeNotesFromPeers
  } = useSudokuBoard({
      difficulty,
      levelId,
      settings,
      onComplete: handleGameComplete,
      onBoardChange: (newBoard) => saveProgress(newBoard),
      onSectionComplete: handleSectionComplete
  });

  const {
      scanUses,
      setScanUses,
      isScanning,
      scanCooldown,
      revealUses,
      setRevealUses,
      revealingCell,
      setRevealingCell,
      animatingCell,
      setAnimatingCell,
      isAutoAvailable,
      handleAutoFill,
      handleScan,
      handleReveal
  } = useGameSkills({
      board,
      setBoard,
      solvedBoard,
      setHistory,
      moveLog,
      selectedCell,
      activeNumber,
      settings,
      difficulty,
      removeNotesFromPeers,
      checkCompletion,
      onSaveProgress: (b, s, r) => saveProgress(b, s, r),
      onSectionComplete: handleSectionComplete
  });

  useEffect(() => {
      const progress = Storage.getLevelProgress(difficulty, levelId);
      if (progress && progress.status === 'in-progress' && progress.boardState) {
          initializeBoard(progress.boardState);
          setInitialTime(progress.timeElapsed);
          setTimer(progress.timeElapsed); 
      } else {
          initializeBoard();
          setInitialTime(0);
          setTimer(0); 
      }
      setIsCompleted(false);
      setIsEnding(false);
      setIsPaused(false);
      setShowRestartConfirm(false);
      setReplayUrl(null);
      setShowReplay(false);
      setAnimatingSections(new Set());

      // Show hint on new level load
      setShowStartHint(true);
      const hintTimer = setTimeout(() => setShowStartHint(false), 5000);
      return () => clearTimeout(hintTimer);
  }, [difficulty, levelId, initializeBoard]);

  useEffect(() => {
    if (savedProgress) {
      if (savedProgress.scanUses !== undefined) setScanUses(savedProgress.scanUses);
      if (savedProgress.revealUses !== undefined) setRevealUses(savedProgress.revealUses);
    } else {
      setScanUses(3);
      setRevealUses(1);
    }
  }, [difficulty, levelId]);

  const generateReplay = () => {
        if (isGeneratingReplay || replayUrl) return;
        setIsGeneratingReplay(true);
        setTimeout(() => {
            try {
                const cleanMoves: ReplayMove[] = [];
                const finalMoveMap = new Map<string, number>();
                moveLog.current.forEach(move => {
                    if (solvedBoard[move.r] && solvedBoard[move.r][move.c] && move.v === solvedBoard[move.r][move.c]) {
                        finalMoveMap.set(`${move.r}-${move.c}`, move.t);
                    }
                });
                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        if (initialBoardRef.current[r] && initialBoardRef.current[r][c] && !initialBoardRef.current[r][c].isFixed) {
                            const t = finalMoveMap.get(`${r}-${c}`) || 0;
                            cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t });
                        }
                    }
                }
                cleanMoves.sort((a, b) => (a.t || 0) - (b.t || 0));

                const isDark = document.documentElement.classList.contains('dark');
                generateReplayVideo(initialBoardRef.current, cleanMoves, difficulty, levelId, isDark)
                    .then(url => {
                        setReplayUrl(url);
                        setIsGeneratingReplay(false);
                    })
                    .catch(err => {
                        console.error("Replay generation error:", err);
                        setIsGeneratingReplay(false);
                    });
            } catch (e) {
                console.error("Replay preparation error:", e);
                setIsGeneratingReplay(false);
            }
        }, 500);
  };

  const handleShareReplay = async () => {
      if (!replayUrl) return;
      try {
          const blob = await fetch(replayUrl).then(r => r.blob());
          const isMp4 = blob.type.includes('mp4');
          const ext = isMp4 ? 'mp4' : 'webm';
          const mime = isMp4 ? 'video/mp4' : 'video/webm';

          const file = new File([blob], `sudoku_${difficulty}_${levelId}.${ext}`, { type: mime });
          if (navigator.share && navigator.canShare({ files: [file] })) {
              await navigator.share({
                  files: [file],
                  title: 'Minimal Sudoku Replay',
                  text: `I solved Level ${levelId} (${difficulty}) in ${formatTimeShort(timer)}!`
              });
          } else {
              const a = document.createElement('a');
              a.href = replayUrl;
              a.download = `sudoku_${difficulty}_${levelId}.${ext}`;
              a.click();
          }
      } catch (e) {
          console.error("Share failed", e);
      }
  };

  const handleRestart = () => {
      sounds.playClick();
      Storage.clearLevelProgress(difficulty, levelId); 
      initializeBoard(); 
      setTimer(0); 
      setScanUses(3); 
      setRevealUses(1); 
      setShowRestartConfirm(false); 
      setIsPaused(false);
      setAnimatingSections(new Set());

      // Reset hint
      setShowStartHint(true);
      setTimeout(() => setShowStartHint(false), 5000);
  };

  const handleBackgroundClick = (e: React.MouseEvent) => {
      if (e.target === e.currentTarget) {
          setSelectedCell(null);
      }
  };

  return (
    <>
      <div className="w-full flex flex-col relative z-30 pt-[60px] pb-2 min-h-[100px]">
          <button onClick={onBack} className="absolute left-6 top-[20px] p-2 rounded-full hover:bg-stone-200/50 transition -ml-2 text-t-icon">
              <Icons.Back className="w-6 h-6" />
          </button>

          <div className="absolute right-6 top-[20px] flex gap-2 -mr-2">
              <button onClick={() => { sounds.playClick(); setIsPaused(true); }} className="p-2 rounded-full hover:bg-stone-200/50 transition text-t-icon">
                  <Icons.Pause className="w-6 h-6" />
              </button>
              <button onClick={onSettingsOpen} className="p-2 rounded-full hover:bg-stone-200/50 transition text-t-icon">
                  <Icons.Settings className="w-6 h-6" />
              </button>
          </div>

          <div className="flex flex-col items-center animate-fade-in -mt-2">
              <span className="text-xs font-bold text-t-secondary uppercase tracking-widest">{difficulty.toUpperCase()} • LEVEL {levelId}</span>
              {settings.showTimer && (
                  <span className="text-2xl font-bold text-t-primary tabular-nums leading-none mt-1">{formatTimeShort(timer)}</span>
              )}
          </div>
      </div>

      <div 
          className="flex-1 w-full flex flex-col items-center justify-start relative cursor-default" 
          onClick={handleBackgroundClick}
      >
         <SudokuGrid 
             board={board}
             selectedCell={selectedCell}
             activeNumber={activeNumber}
             conflicts={conflicts}
             revealingCell={revealingCell}
             animatingCell={animatingCell}
             isScanning={isScanning}
             animatingSections={animatingSections}
             settings={settings}
             numberColor={numberColor}
             onCellClick={(e, r, c) => handleCellClick(r, c, isPaused, isCompleted)}
         />

         <div className="w-full max-w-md px-6 mt-4 flex flex-col gap-6" onClick={(e) => e.stopPropagation()}>
             <GameControls 
                 canUndo={history.length > 0}
                 canErase={!!selectedCell && board[selectedCell[0]][selectedCell[1]].value !== null && !board[selectedCell[0]][selectedCell[1]].isFixed}
                 isPencilMode={isPencilMode}
                 onUndo={(e) => handleUndo(isPaused, isCompleted)}
                 onErase={(e) => handleErase(isPaused, isCompleted)}
                 onTogglePencil={() => { sounds.playClick(); setIsPencilMode(!isPencilMode); }}
                 purchasedSkills={purchasedSkills}
                 isAutoAvailable={isAutoAvailable}
                 scanUses={scanUses}
                 isScanning={isScanning}
                 scanCooldown={scanCooldown}
                 revealUses={revealUses}
                 revealingCell={revealingCell}
                 onAutoFill={() => handleAutoFill(purchasedSkills)}
                 onScan={() => handleScan(isPaused, isCompleted)}
                 onReveal={() => handleReveal(isPaused, isCompleted)}
             />

             <NumberPad 
                 activeNumber={activeNumber}
                 numberCounts={numberCounts}
                 isPencilMode={isPencilMode}
                 numberColor={numberColor}
                 onNumberClick={(e, n) => handleNumberInput(n, isPaused, isCompleted)}
             />
         </div>

         <div className={`mt-5 mb-4 pointer-events-none transition-opacity duration-1000 ${showStartHint ? 'opacity-100' : 'opacity-0'}`}>
             <span className="text-base font-medium text-stone-400 dark:text-stone-500 tracking-wide">Tap here to deselect</span>
         </div>
      </div>

      {(isPaused || showRestartConfirm) && (
          <div className="fixed inset-0 bg-stone-50/90 dark:bg-stone-900/90 backdrop-blur-sm z-[100] flex items-center justify-center animate-fade-in">
              {!showRestartConfirm ? (
                  <div className="flex flex-col gap-4 w-48 animate-pop">
                    <h2 className="text-2xl font-bold text-stone-800 dark:text-t-primary mb-4 text-center">Game Paused</h2>
                    <button onClick={() => { sounds.playClick(); setIsPaused(false); }} className="flex items-center justify-center gap-2 p-4 bg-stone-800 text-white dark:bg-blue-600 dark:text-white rounded-xl shadow-lg active:scale-95 transition hover:opacity-90">
                        <Icons.Play className="w-5 h-5 fill-current" /> Resume
                    </button>
                    <button onClick={() => { sounds.playClick(); setShowRestartConfirm(true); }} className="flex items-center justify-center gap-2 p-4 bg-white text-stone-800 border border-stone-200 dark:bg-t-surface dark:text-t-primary dark:border-t-border rounded-xl active:scale-95 transition hover:bg-stone-50 dark:hover:bg-t-surface-sec">
                        <Icons.Reset className="w-5 h-5" /> Restart Level
                    </button>
                    <button onClick={() => { sounds.playClick(); onBack(); }} className="flex items-center justify-center gap-2 p-4 text-stone-500 hover:text-stone-800 dark:text-t-secondary dark:hover:text-t-primary transition font-medium">
                        Quit Game
                    </button>
                  </div>
              ) : (
                  <div className="bg-white dark:bg-t-surface p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop">
                     <h3 className="text-lg font-bold text-stone-800 dark:text-t-primary mb-2">Restart Level?</h3>
                     <p className="text-stone-500 dark:text-t-secondary text-sm mb-6">Are you sure? This will reset your progress on this level.</p>
                     <div className="flex gap-3">
                         <button onClick={() => { sounds.playClick(); setShowRestartConfirm(false); }} className="flex-1 py-3 text-stone-600 bg-stone-100 dark:bg-t-surface-sec dark:text-t-primary rounded-xl font-medium active:scale-95 transition">Cancel</button>
                         <button onClick={handleRestart} className="flex-1 py-3 text-white bg-red-500 rounded-xl font-medium shadow-md active:scale-95 transition">Restart</button>
                     </div>
                  </div>
              )}
          </div>
      )}

      {isCompleted && (
          <WinModal 
              difficulty={difficulty}
              levelId={levelId}
              timer={timer}
              points={earnedPoints}
              isGeneratingReplay={isGeneratingReplay}
              replayUrl={replayUrl}
              showReplay={showReplay}
              onReplay={(e) => { e.stopPropagation(); setShowReplay(true); }}
              onShareReplay={handleShareReplay}
              onCloseReplay={() => setShowReplay(false)}
              onBack={onBack}
              onReturnToMenu={onReturnToMenu}
          />
      )}
    </>
  );
};

import React from 'react';
import { Icons } from '../ui/Icons';
import { Difficulty } from '../../types';

interface WinModalProps {
    difficulty: Difficulty;
    levelId: number;
    timer: number;
    points: number;
    isGeneratingReplay: boolean;
    replayUrl: string | null;
    showReplay: boolean;
    onReplay: (e: React.MouseEvent) => void;
    onShareReplay: () => void;
    onCloseReplay: () => void;
    onBack: (e: React.MouseEvent) => void;
    onReturnToMenu: (e: React.MouseEvent) => void;
}

export const WinModal: React.FC<WinModalProps> = ({
    difficulty,
    levelId,
    timer,
    points,
    isGeneratingReplay,
    replayUrl,
    showReplay,
    onReplay,
    onShareReplay,
    onCloseReplay,
    onBack,
    onReturnToMenu
}) => {
    const formatTime = (seconds: number) => {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${mins}:${secs.toString().padStart(2, '0')}`;
    };

    const formatFullTime = (seconds: number) => {
        const h = Math.floor(seconds / 3600);
        const m = Math.floor((seconds % 3600) / 60);
        const s = seconds % 60;

        const hStr = h > 0 ? `${h}:` : '';
        const mStr = h > 0 ? m.toString().padStart(2, '0') : m.toString();
        const sStr = s.toString().padStart(2, '0');

        return `${hStr}${mStr}:${sStr}`;
    };

    if (showReplay && replayUrl) {
        return (
            <div className="fixed inset-0 bg-black z-[110] flex flex-col items-center justify-center">
                 {/* Replay Metadata Header */}
                 <div className="absolute top-10 left-0 right-0 flex flex-col items-center pointer-events-none z-20">
                    <div className="text-xs font-bold text-stone-400 uppercase tracking-widest mb-1">
                        {difficulty.toUpperCase()} &bull; LEVEL {levelId}
                    </div>
                    <div className="text-xl font-bold text-white tabular-nums tracking-tight">
                        {formatFullTime(timer)}
                    </div>
                 </div>

                 <div className="relative w-full max-w-[1080px] aspect-square bg-stone-900 shadow-2xl overflow-hidden rounded-none sm:rounded-2xl">
                      <video 
                          src={replayUrl} 
                          autoPlay 
                          loop 
                          playsInline 
                          className="w-full h-full object-cover"
                      />
                 </div>

                 <div className="absolute bottom-10 left-0 right-0 flex items-center justify-center gap-4 px-6">
                     <button 
                         onClick={onShareReplay}
                         className="px-8 py-4 bg-white text-black rounded-full font-bold shadow-xl active:scale-95 transition flex items-center gap-2"
                     >
                         <Icons.Diamond className="w-5 h-5 text-blue-500" /> Share
                     </button>
                     <button 
                         onClick={onCloseReplay}
                         className="p-4 bg-stone-800 text-white rounded-full font-bold shadow-xl active:scale-95 transition"
                     >
                         <Icons.Close className="w-6 h-6" />
                     </button>
                 </div>
            </div>
        );
    }

    return (
        <div className="fixed inset-0 bg-green-500/50 backdrop-blur-sm z-[100] flex flex-col items-center justify-center text-white animate-fade-in">
            <div className="bg-white dark:bg-stone-800 text-stone-800 dark:text-t-primary p-8 rounded-2xl shadow-2xl w-80 text-center animate-pop relative overflow-hidden">
                <div className="w-20 h-20 bg-green-100 dark:bg-green-900 rounded-full flex items-center justify-center mx-auto mb-4 text-green-500 dark:text-green-400 relative z-10"><Icons.Check className="w-10 h-10 animate-scale-loop" /></div>
                <div className="text-xs font-bold text-stone-400 dark:text-stone-400 uppercase tracking-widest mb-1 relative z-10">{difficulty.toUpperCase()} &bull; Level {levelId}</div>
                <h2 className="text-2xl font-bold mb-2 relative z-10">Solved!</h2>
                <p className="text-stone-500 dark:text-stone-300 mb-2 text-sm relative z-10">You earned</p>
                <div className="flex items-center justify-center gap-2 mb-4 relative z-10"><div className="text-blue-500"><Icons.Diamond className="w-6 h-6 fill-current" /></div><span className="text-3xl font-bold text-stone-800 dark:text-t-primary">+{points}</span></div>
                <p className="text-stone-400 dark:text-stone-400 mb-2 text-xs uppercase tracking-wide relative z-10">Time</p>
                <p className="text-2xl font-medium mb-6 tabular-nums relative z-10">{formatFullTime(timer)}</p>

                {/* Replay Button */}
                {isGeneratingReplay ? (
                    <div className="flex items-center justify-center gap-2 mb-6 text-sm text-stone-500 animate-pulse">
                        <Icons.Video className="w-4 h-4" /> Generating Replay...
                    </div>
                ) : replayUrl && (
                    <button 
                       onClick={onReplay}
                       className="w-full py-3 bg-blue-500 text-white rounded-xl font-bold mb-4 shadow-lg active:scale-95 transition flex items-center justify-center gap-2 hover:bg-blue-600 relative z-10"
                    >
                       <Icons.Video className="w-5 h-5" /> Watch Replay
                    </button>
                )}

                <div className="flex flex-col gap-3 relative z-10">
                  <button onClick={onBack} className="w-full py-3 bg-stone-800 text-white dark:bg-stone-100 dark:text-stone-900 rounded-xl font-medium hover:bg-stone-700 dark:hover:bg-stone-200 active:scale-95 transition shadow-lg active:opacity-80">Back to Levels</button>
                  <button onClick={onReturnToMenu} className="w-full py-3 bg-white text-stone-600 border border-stone-200 dark:bg-stone-800 dark:text-stone-200 dark:border-stone-600 rounded-xl font-medium hover:bg-stone-50 dark:hover:bg-stone-700 active:scale-95 transition active:opacity-80">Back to Menu</button>
                </div>
            </div>
        </div>
    );
};

import { Board } from '../types';

export interface ReplayMove {
  row: number;
  col: number;
  value: number;
  t?: number;
}

// Refined Audio Synthesis Helper with precise scheduling support
function createReplayAudio(ctx: AudioContext, dest: MediaStreamAudioDestinationNode) {
    // 1. Standard Move Pop (Lower, accumulation feel)
    const playPop = (progress: number, t: number) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(dest);

        // Pitch scale: Exponential from C5 to C6 based on progress
        const freq = 523.25 * Math.pow(2, progress);
        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, t);

        // Crisp, audible pop
        gain.gain.setValueAtTime(0, t);
        gain.gain.linearRampToValueAtTime(0.5, t + 0.01);
        gain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);

        osc.start(t);
        osc.stop(t + 0.1);
    };

    // 2. Subtle Premium Victory (Soft Chord Swell)
    const playVictory = (t: number) => {
        const notes = [523.25, 659.25, 783.99, 987.77];

        notes.forEach((freq, i) => {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.connect(gain);
            gain.connect(dest);

            osc.type = 'sine';
            osc.frequency.setValueAtTime(freq, t);

            const start = t + (i * 0.05); 

            gain.gain.setValueAtTime(0, start);
            gain.gain.linearRampToValueAtTime(0.15, start + 0.1); 
            gain.gain.exponentialRampToValueAtTime(0.001, start + 2.0); 

            osc.start(start);
            osc.stop(start + 2.5);
        });
    };

    return { playPop, playVictory };
}

export async function generateReplayVideo(
  initialBoard: Board,
  moves: ReplayMove[],
  difficulty: string,
  levelId: number,
  isDark: boolean
): Promise<string | null> {
  if (typeof document === 'undefined') return null;

  const canvas = document.createElement('canvas');
  const size = 1080;
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  // Initialize Audio
  const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();

  if (audioCtx.state === 'suspended') {
      try {
        await audioCtx.resume();
      } catch (e) {
        console.warn("Could not resume audio context", e);
      }
  }

  const dest = audioCtx.createMediaStreamDestination();
  const { playPop, playVictory } = createReplayAudio(audioCtx, dest);

  // Configuration
  const FPS = 30;
  const INTRO_MS = 800;
  const FILL_MS = Math.max(3000, moves.length * 100); 
  const OUTRO_MS = 2500;

  const INTRO_FRAMES = Math.floor((INTRO_MS / 1000) * FPS);
  const FILL_FRAMES = Math.floor((FILL_MS / 1000) * FPS);
  const OUTRO_FRAMES = Math.floor((OUTRO_MS / 1000) * FPS);
  const TOTAL_FRAMES = INTRO_FRAMES + FILL_FRAMES + OUTRO_FRAMES;

  const c = {
    bg: isDark ? '#1c1917' : '#fafaf9',
    boardBg: isDark ? '#292524' : '#ffffff',
    gridLineThin: isDark ? '#57534e' : '#e7e5e4',
    gridLineThick: isDark ? '#a8a29e' : '#78716c',
    textFixed: isDark ? '#f5f5f4' : '#292524',
    textInput: '#3b82f6',
    successBorder: '#10b981',
    watermark: isDark ? '#57534e' : '#a8a29e',
  };

  const padding = 120;
  const boardSize = size - (padding * 2);
  const cellSize = boardSize / 9;
  const startX = padding;
  const startY = padding;

  const moveCount = moves.length;
  const moveFrames = new Int32Array(moveCount);
  const BUFFER_FRAMES = 6; 
  const availableFrames = Math.max(1, FILL_FRAMES - BUFFER_FRAMES);
  const frameStep = availableFrames / Math.max(1, moveCount);

  for (let i = 0; i < moveCount; i++) {
      moveFrames[i] = INTRO_FRAMES + Math.floor(i * frameStep);
  }

  // Draw Function (now purely visual)
  const drawBoard = (frame: number) => {
      ctx.fillStyle = c.bg;
      ctx.fillRect(0, 0, size, size);

      // Animation removed for a cleaner, more immediate look
      let globalOpacity = 1;
      let scale = 1;

      ctx.save();
      ctx.translate(size/2, size/2);
      ctx.scale(scale, scale);
      ctx.translate(-size/2, -size/2);
      ctx.globalAlpha = globalOpacity;

      // Header
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = c.textFixed;
      ctx.font = 'bold 40px "Outfit", sans-serif';
      ctx.fillText(`${difficulty.toUpperCase()} • LEVEL ${levelId}`, size/2, padding / 2);

      // Watermark
      ctx.fillStyle = c.watermark;
      ctx.font = '500 30px "Outfit", sans-serif';
      ctx.fillText("OKU: SUDOKU", size/2, size - (padding / 2));

      // Board BG
      ctx.shadowColor = "rgba(0,0,0,0.1)";
      ctx.shadowBlur = 30;
      ctx.shadowOffsetY = 10;
      ctx.fillStyle = c.boardBg;
      const r = 32;
      ctx.beginPath();
      ctx.roundRect(startX, startY, boardSize, boardSize, r);
      ctx.fill();
      ctx.shadowBlur = 0;
      ctx.shadowOffsetY = 0;

      // Clip
      ctx.save();
      ctx.beginPath();
      ctx.roundRect(startX, startY, boardSize, boardSize, r);
      ctx.clip();

      // Lines
      ctx.lineCap = 'butt';
      for (let i = 1; i < 9; i++) {
          const pos = i * cellSize;
          const isThick = i % 3 === 0;
          ctx.lineWidth = isThick ? 6 : 2;
          ctx.strokeStyle = isThick ? c.gridLineThick : c.gridLineThin;

          ctx.beginPath();
          ctx.moveTo(startX + pos, startY);
          ctx.lineTo(startX + pos, startY + boardSize);
          ctx.stroke();

          ctx.beginPath();
          ctx.moveTo(startX, startY + pos);
          ctx.lineTo(startX + boardSize, startY + pos);
          ctx.stroke();
      }
      ctx.restore();

      // Fixed Nums
      ctx.font = `600 ${cellSize * 0.6}px "Outfit", sans-serif`;
      ctx.fillStyle = c.textFixed;

      initialBoard.forEach(row => {
          row.forEach(cell => {
              if (cell.isFixed && cell.value) {
                  const cx = startX + (cell.col * cellSize) + (cellSize / 2);
                  const cy = startY + (cell.row * cellSize) + (cellSize / 2);
                  ctx.fillText(cell.value.toString(), cx, cy + (cellSize * 0.05));
              }
          });
      });

      // Moves
      if (frame >= INTRO_FRAMES) {
          ctx.font = `500 ${cellSize * 0.6}px "Outfit", sans-serif`;
          ctx.fillStyle = c.textInput;

          for (let i = 0; i < moveCount; i++) {
              const startFrame = moveFrames[i];

              if (frame >= startFrame) {
                  const move = moves[i];
                  const cx = startX + (move.col * cellSize) + (cellSize / 2);
                  const cy = startY + (move.row * cellSize) + (cellSize / 2);

                  const age = frame - startFrame;
                  let numScale = 1;
                  if (age < 6) {
                      numScale = 1.0 + (0.5 * (1 - (age / 6)));
                  }

                  ctx.save();
                  ctx.translate(cx, cy);
                  ctx.scale(numScale, numScale);
                  ctx.fillText(move.value.toString(), 0, (cellSize * 0.05));
                  ctx.restore();
              }
          }
      }

      // Success Outro
      if (frame >= INTRO_FRAMES + FILL_FRAMES) {
          const outroAge = frame - (INTRO_FRAMES + FILL_FRAMES);
          const BORDER_FRAME = 0;

          if (outroAge >= BORDER_FRAME) {
              const visualAge = outroAge - BORDER_FRAME;
              const alpha = Math.min(1, (visualAge + 1) / 5);

              ctx.lineWidth = 12;
              ctx.strokeStyle = c.successBorder;
              ctx.globalAlpha = alpha * globalOpacity;

              ctx.beginPath();
              ctx.roundRect(startX, startY, boardSize, boardSize, r);
              ctx.stroke();
          }
      }

      ctx.restore();
  };

  // Pre-render first frame
  drawBoard(0);

  // Create Stream & Recorder
  const stream = canvas.captureStream(FPS);
  const audioTrack = dest.stream.getAudioTracks()[0];
  if (audioTrack) {
      stream.addTrack(audioTrack);
  }

  let mimeType = 'video/webm';
  const possibleTypes = [
    'video/mp4; codecs=avc1',
    'video/mp4',
    'video/webm; codecs=vp9',
    'video/webm'
  ];

  for (const t of possibleTypes) {
      if (MediaRecorder.isTypeSupported(t)) {
          mimeType = t;
          break;
      }
  }

  let mediaRecorder: MediaRecorder;
  try {
      mediaRecorder = new MediaRecorder(stream, { mimeType, videoBitsPerSecond: 5000000 });
  } catch (e) {
      console.error("MediaRecorder creation failed", e);
      audioCtx.close();
      return null;
  }

  const chunks: Blob[] = [];
  mediaRecorder.ondataavailable = (e) => {
    if (e.data.size > 0) chunks.push(e.data);
  };

  const recordingPromise = new Promise<string | null>((resolve) => {
    mediaRecorder.onstop = () => {
      audioCtx.close();
      if (chunks.length === 0) {
           resolve(null);
           return;
      }
      const blob = new Blob(chunks, { type: mimeType });
      const url = URL.createObjectURL(blob);
      resolve(url);
    };
    mediaRecorder.onerror = (e) => {
        console.error("MediaRecorder error", e);
        audioCtx.close();
        resolve(null);
    };
  });

  // Start Recording
  try {
      mediaRecorder.start();
  } catch (e) {
      console.error("MediaRecorder start failed", e);
      audioCtx.close();
      return null;
  }

  // PRE-SCHEDULE AUDIO
  // We use the audioCtx timeline to schedule all events at the exact predicted frame times
  const baseTime = audioCtx.currentTime;

  // Schedule move pops
  for (let i = 0; i < moveCount; i++) {
    const scheduledTime = baseTime + (moveFrames[i] / FPS);
    playPop(i / Math.max(1, moveCount), scheduledTime);
  }

  // Schedule victory swell (happens exactly when outro starts)
  const victoryScheduledTime = baseTime + ((INTRO_FRAMES + FILL_FRAMES) / FPS);
  playVictory(victoryScheduledTime);

  // EXECUTION LOOP
  let currentFrame = 1;
  const intervalMs = 1000 / FPS;

  return new Promise((resolve) => {
      const interval = setInterval(() => {
          try {
              drawBoard(currentFrame);
              currentFrame++;

              if (currentFrame >= TOTAL_FRAMES) {
                  clearInterval(interval);
                  // Ensure audio has finished captured before stopping
                  setTimeout(() => {
                    mediaRecorder.stop();
                    recordingPromise.then(resolve);
                  }, 100);
              }
          } catch (e) {
              console.error("Error during recording loop", e);
              clearInterval(interval);
              try { mediaRecorder.stop(); } catch(e2) {}
              resolve(null);
          }
      }, intervalMs);
  });
}
